using UnityEngine;using UnityEditor;
[CustomEditor(typeof(TrainingMotionAction))]public sealed class TrainingMotionActionEditor:Editor {
 TrainingMotionAction draft;SerializedObject data;int frame;bool mirror;string status="Draft only. Save explicitly.";
 void OnEnable(){Reload();}void OnDisable(){if(draft!=null)DestroyImmediate(draft);}
 void Reload(){if(draft!=null)DestroyImmediate(draft);draft=Instantiate((TrainingMotionAction)target);draft.hideFlags=HideFlags.HideAndDontSave;draft.name=target.name;data=new SerializedObject(draft);}
 public override void OnInspectorGUI(){if(Application.isPlaying){EditorGUILayout.HelpBox("Author outside Play. Runtime never saves this asset.",MessageType.Info);return;}if(draft==null)Reload();data.Update();EditorGUILayout.LabelField("Local forward X / up Y, meters. No movement performance.");EditorGUILayout.PropertyField(data.FindProperty("loop"));EditorGUILayout.PropertyField(data.FindProperty("poses"),true);data.ApplyModifiedProperties();EditorGUILayout.HelpBox("Hurt part IDs refer to the character Hurtboxes asset; priority/defense stay there. Missing parts use existing geometry. Keep IDs unchanged.",MessageType.Info);frame=EditorGUILayout.IntField("Preview frame (60Hz)",Mathf.Max(0,frame));mirror=EditorGUILayout.Toggle("Mirror left",mirror);Preview();EditorGUILayout.BeginHorizontal();if(GUILayout.Button("Save same asset")){if(!draft.Validate(out var error))status=error;else{SaveDraft((TrainingMotionAction)target,draft);status="Saved same authoritative asset";}}if(GUILayout.Button("Cancel / reload")){Reload();status="Unsaved draft discarded";}EditorGUILayout.EndHorizontal();EditorGUILayout.HelpBox(status,MessageType.Info);}
 public static void SaveDraft(TrainingMotionAction target,TrainingMotionAction draft){if(Application.isPlaying)throw new System.InvalidOperationException("No authoring save during Play");if(!draft.Validate(out var error))throw new System.ArgumentException(error);var name=target.name;Undo.RecordObject(target,"Save motion action draft");EditorUtility.CopySerialized(draft,target);target.name=name;EditorUtility.SetDirty(target);AssetDatabase.SaveAssetIfDirty(target);}
 void Preview(){var pose=draft.Sample(frame);if(pose==null)return;var r=GUILayoutUtility.GetRect(100,250,GUILayout.ExpandWidth(true));EditorGUI.DrawRect(r,new Color(.06f,.08f,.1f));float scale=100;var foot=new Vector2(r.center.x,r.yMax-8);float visualScale=1;foreach(var guid in AssetDatabase.FindAssets("t:TrainingApprovedCharacter")){var owner=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>(AssetDatabase.GUIDToAssetPath(guid));if(owner!=null&&(owner.idleAction==target||owner.forwardWalkAction==target)&&owner.bodyCalibration!=null){visualScale=owner.bodyCalibration.VisualScale;break;}}var sprite=pose.sprite;float pixels=scale*visualScale/sprite.pixelsPerUnit;var sizeSprite=sprite.rect.size*pixels;var anchor=foot+new Vector2(pose.visualOffset.x,-pose.visualOffset.y)*scale;var draw=new Rect(anchor.x-sprite.pivot.x*pixels,anchor.y-(sprite.rect.height-sprite.pivot.y)*pixels,sizeSprite.x,sizeSprite.y);var previous=GUI.matrix;if(mirror)GUI.matrix=Matrix4x4.TRS(new Vector3(2*foot.x,0,0),Quaternion.identity,new Vector3(-1,1,1))*previous;GUI.BeginClip(r);draw.position-=r.position;var uv=new Rect(sprite.rect.x/sprite.texture.width,sprite.rect.y/sprite.texture.height,sprite.rect.width/sprite.texture.width,sprite.rect.height/sprite.texture.height);GUI.DrawTextureWithTexCoords(draw,sprite.texture,uv,true);GUI.EndClip();GUI.matrix=previous;
 Handles.BeginGUI();Handles.color=Color.gray;Handles.DrawLine(new Vector2(r.x,foot.y),new Vector2(r.xMax,foot.y));foreach(var h in pose.hurt){var c=foot+new Vector2(h.center.x*(mirror?-1:1),-h.center.y)*scale;var size=h.size*scale;Handles.color=Color.green;Handles.DrawWireCube(c,size);}Handles.EndGUI();EditorGUILayout.LabelField("Sprite",pose.sprite.name);EditorGUILayout.LabelField("Calibrated sprite and hurt outlines. Forward X / up Y. No simulation or hit resolution.");}
}
